SELECT game_id AS "gameId", cooldown_id AS "cooldownId", ability_id AS "abilityId", duration_formula_key AS "durationFormulaKey", starts_on_phase_id AS "startsOnPhaseId", group_key AS "groupKey", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.ability_cooldowns WHERE game_id = #{gameId}
AND ability_id = #{abilityId}
ORDER BY ability_id, cooldown_id
